package cc.huevia.ncp;

import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

/** Independent geometry, pixel, ownership and bounded-allocation checks for local editing. */
public final class PhotoLocalEditsTest {
    private static int checks;
    private static final PresetPreviewProfile ORIGINAL=new PresetPreviewProfile(){public String registrationName(){return "original";}public String modelVersion(){return "original";}public double mapTone(double v){return v;}public int applyArgb(int p){return p;}};
    public static void main(String[] args)throws Exception{model();coverage();colour();orientation();cloneOrientationTies();cloneOverlap();cancellation();streaming();System.out.println("PASS "+checks+" local-edit checks; EXIF1-8, masks, clone snapshot, serialization, cancellation, 24MP bounded stream.");}
    private static void check(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
    private static void rejects(Runnable operation,String message){boolean rejected=false;try{operation.run();}catch(IllegalArgumentException expected){rejected=true;}check(rejected,message);}
    private static void model()throws Exception{
        check(PhotoLocalEdits.NONE.isEmpty()&&PhotoLocalEdits.NONE.isNeutral(),"empty edits");double[] points={.1,.2,.6,.7};PhotoLocalEdits.Mask brush=PhotoLocalEdits.Mask.brush(points,.06,.7);points[0]=.9;check(brush.points()[0]==.1,"input brush array copied");double[] exposed=brush.points();exposed[0]=.9;check(brush.points()[0]==.1,"output brush array copied");
        PhotoLocalEdits edits=PhotoLocalEdits.NONE.add(brush.parameters(12,-25,17)).add(PhotoLocalEdits.Mask.radial(.3,.4).parameters(-8,5,60)).add(PhotoLocalEdits.Mask.linear(.2,.8,.8,.2).inverted(true)).add(new PhotoLocalEdits.Clone(.2,.3,.7,.8,.04,.8,true));ByteArrayOutputStream b=new ByteArrayOutputStream();edits.write(new DataOutputStream(b));PhotoLocalEdits read=PhotoLocalEdits.read(new DataInputStream(new ByteArrayInputStream(b.toByteArray())));check(read.equals(edits)&&read.hashCode()==edits.hashCode()&&read.identity().equals(edits.identity()),"serialization exact");check(!read.identity().equals(read.removeMask(0).identity()),"identity binds masks");check(!read.identity().equals(read.removeClone(0).identity()),"identity binds clone");check(PhotoLocalEdits.NONE.add(brush).isNeutral(),"blank mask is render-neutral");check(LocalEditsPreviewProfile.of(ORIGINAL,PhotoLocalEdits.NONE.add(brush))==ORIGINAL,"blank mask preserves old profile");check(LocalEditsPreviewProfile.of(ORIGINAL,PhotoLocalEdits.NONE.add(brush.parameters(10,0,0).enabled(false)))==ORIGINAL,"disabled mask preserves old profile");
        boolean immutable=false;try{edits.masks().clear();}catch(UnsupportedOperationException expected){immutable=true;}check(immutable,"immutable collection");rejects(()->PhotoLocalEdits.Mask.radial(Double.NaN,.2),"NaN rejected");rejects(()->PhotoLocalEdits.Mask.radial(.2,Double.POSITIVE_INFINITY),"infinity rejected");rejects(()->PhotoLocalEdits.Mask.brush(new double[]{.2,.3,.4},.1,.2),"odd brush rejected");rejects(()->PhotoLocalEdits.Mask.linear(.2,.2,.2,.2),"empty gradient rejected");rejects(()->brush.parameters(31,0,0),"exposure bound");rejects(()->new PhotoLocalEdits.Clone(.2,.3,.4,.5,.3,.2,true),"clone radius bound");ArrayList<PhotoLocalEdits.Mask> many=new ArrayList<>();for(int i=0;i<17;i++)many.add(brush);rejects(()->new PhotoLocalEdits(many,Collections.emptyList()),"mask count bound");
        for(int bytes=0;bytes<Math.min(64,b.size());bytes++){try{PhotoLocalEdits.read(new DataInputStream(new ByteArrayInputStream(Arrays.copyOf(b.toByteArray(),bytes))));throw new AssertionError("truncated model accepted");}catch(IOException expected){checks++;}}
        byte[] invalid=b.toByteArray().clone();invalid[7]=(byte)255;boolean bad=false;try{PhotoLocalEdits.read(new DataInputStream(new ByteArrayInputStream(invalid)));}catch(IOException expected){bad=true;}check(bad,"encoded excessive count rejected");
    }
    private static void coverage(){PhotoLocalEdits.Mask radial=PhotoLocalEdits.Mask.radial(.5,.5);check(radial.weight(.5,.5,400,300)==1,"radial centre");check(radial.weight(.9,.5,400,300)==0,"radial outside");double edge=radial.weight(.5+.22*.8,.5,400,300);check(edge>0&&edge<1,"radial feather");for(int i=0;i<=20;i++){double x=i/20.0;check(Math.abs(radial.weight(x,.5,400,300)+radial.inverted(true).weight(x,.5,400,300)-1)<1e-12,"inverse coverage");}PhotoLocalEdits.Mask gradient=PhotoLocalEdits.Mask.linear(.2,.5,.8,.5);check(gradient.weight(.1,.5,400,300)==0&&gradient.weight(.9,.5,400,300)==1,"gradient ends");check(Math.abs(gradient.weight(.5,.5,400,300)-.5)<1e-12,"gradient middle");PhotoLocalEdits.Mask brush=PhotoLocalEdits.Mask.brush(new double[]{.2,.5,.8,.5},.1,.5);check(brush.weight(.5,.5,400,300)==1,"brush segment connected");check(brush.weight(.5,.7,400,300)==0,"brush extent uses short side");check(brush.weight(.5,.5,400,300)==brush.weight(.5,.5,1600,1200),"coverage resolution invariant");}
    private static void colour()throws Exception{int width=21,height=21;int[] source=new int[width*height];Arrays.fill(source,0x7f808080);PhotoLocalEdits edits=PhotoLocalEdits.NONE.add(PhotoLocalEdits.Mask.radial(.5,.5).parameters(10,0,0));int[] output=render(source,width,height,edits,1);check(output[10*width+10]==0x7fb0b0b0,"one EV linear centre");check(output[0]==source[0],"outside unchanged");for(int i=0;i<source.length;i++)check((source[i]>>>24)==(output[i]>>>24),"alpha preserved");int[] neutral=render(source,width,height,PhotoLocalEdits.NONE,1);check(Arrays.equals(neutral,source),"neutral exact");int[] warm=render(source,width,height,PhotoLocalEdits.NONE.add(PhotoLocalEdits.Mask.radial(.5,.5).parameters(0,100,0)),1);int centre=warm[10*width+10];check(((centre>>>16)&255)>(centre&255),"temperature warms selected centre");Arrays.fill(source,0xffd07020);int[] gray=render(source,width,height,PhotoLocalEdits.NONE.add(PhotoLocalEdits.Mask.radial(.5,.5).parameters(0,0,-100)),1);centre=gray[10*width+10];check(((centre>>>16)&255)==((centre>>>8)&255)&&((centre>>>8)&255)==(centre&255),"local saturation zero gives gray");}
    private static void orientation()throws Exception{int ow=47,oh=31;int[] oriented=new int[ow*oh];for(int y=0;y<oh;y++)for(int x=0;x<ow;x++)oriented[y*ow+x]=0xff000000|((x*5+17)&255)<<16|((y*7+21)&255)<<8|((x*3+y*2)&255);PhotoLocalEdits edits=PhotoLocalEdits.NONE.add(PhotoLocalEdits.Mask.radial(.28,.35).parameters(9,35,-18)).add(PhotoLocalEdits.Mask.linear(.2,.8,.82,.1).parameters(-6,-20,10)).add(PhotoLocalEdits.Mask.brush(new double[]{.1,.15,.45,.2,.6,.7},.09,.65).parameters(5,10,-20)).add(new PhotoLocalEdits.Clone(7.5/ow,8.5/oh,34.5/ow,20.5/oh,.08,.5,true));int[] expected=render(oriented,ow,oh,edits,1);
        for(int exif=1;exif<=8;exif++){int rw=exif>=5?oh:ow,rh=exif>=5?ow:oh;int[] raw=new int[rw*rh];for(int y=0;y<rh;y++)for(int x=0;x<rw;x++){double nx=(x+.5)/rw,ny=(y+.5)/rh,ox=LocalEditsPreviewProfile.orientedX(nx,ny,exif),oy=LocalEditsPreviewProfile.orientedY(nx,ny,exif);check(Math.abs(LocalEditsPreviewProfile.rawX(ox,oy,exif)-nx)<1e-12&&Math.abs(LocalEditsPreviewProfile.rawY(ox,oy,exif)-ny)<1e-12,"EXIF inverse "+exif);int ix=(int)Math.round(ox*ow-.5),iy=(int)Math.round(oy*oh-.5);raw[y*rw+x]=oriented[iy*ow+ix];}int[] actual=render(raw,rw,rh,edits,exif);for(int y=0;y<rh;y++)for(int x=0;x<rw;x++){double nx=(x+.5)/rw,ny=(y+.5)/rh;int ix=(int)Math.round(LocalEditsPreviewProfile.orientedX(nx,ny,exif)*ow-.5),iy=(int)Math.round(LocalEditsPreviewProfile.orientedY(nx,ny,exif)*oh-.5);check(actual[y*rw+x]==expected[iy*ow+ix],"raw/oriented pixels exact EXIF"+exif+" at"+x+","+y);}}
    }
    private static void cloneOverlap()throws Exception{int w=16,h=16;int[] original=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)original[y*w+x]=0x42000000|x*12<<16|y*12<<8|33;PhotoLocalEdits edits=PhotoLocalEdits.NONE.add(new PhotoLocalEdits.Clone(7.5/w,8.5/h,8.5/w,8.5/h,.25,0,true));int[] result=render(original,w,h,edits,1);check((result[8*w+8]>>>24)==0x42,"clone preserves destination alpha"); // Source alpha deliberately low; blend is proportional to its coverage.
        int[] opaque=original.clone();for(int i=0;i<opaque.length;i++)opaque[i]|=0xff000000;result=render(opaque,w,h,edits,1);check(result[8*w+8]==opaque[8*w+7],"clone centre from explicit source");check(result[8*w+9]==opaque[8*w+8],"overlap source is snapshot, no write feedback");check(result[0]==opaque[0],"clone outside unchanged");PhotoLocalEdits off=PhotoLocalEdits.NONE.add(edits.clones().get(0).enabled(false));check(Arrays.equals(render(opaque,w,h,off,1),opaque),"disabled clone neutral");int[] edge=render(opaque,w,h,PhotoLocalEdits.NONE.add(new PhotoLocalEdits.Clone(0,8.5/h,8.5/w,8.5/h,.1,0,true)),1);check(edge[8*w+8]==opaque[8*w],"source boundary selects edge pixel");}
    private static void cloneOrientationTies()throws Exception{int ow=32,oh=24;int[] original=new int[ow*oh];for(int y=0;y<oh;y++)for(int x=0;x<ow;x++)original[y*ow+x]=0xff000000|x*7<<16|y*9<<8|(x+y)*3;PhotoLocalEdits edit=PhotoLocalEdits.NONE.add(new PhotoLocalEdits.Clone(.375,.375,.640625,.6875,.12,.5,true)).add(new PhotoLocalEdits.Clone(0,.5,.25,.25,.06,.25,true));int[] expected=render(original,ow,oh,edit,1);for(int e=1;e<=8;e++){int w=e>=5?oh:ow,h=e>=5?ow:oh;int[] raw=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int ox=(int)Math.round(LocalEditsPreviewProfile.orientedX((x+.5)/w,(y+.5)/h,e)*ow-.5),oy=(int)Math.round(LocalEditsPreviewProfile.orientedY((x+.5)/w,(y+.5)/h,e)*oh-.5);raw[y*w+x]=original[oy*ow+ox];}int[] output=render(raw,w,h,edit,e);for(int y=0;y<h;y++)for(int x=0;x<w;x++){int ox=(int)Math.round(LocalEditsPreviewProfile.orientedX((x+.5)/w,(y+.5)/h,e)*ow-.5),oy=(int)Math.round(LocalEditsPreviewProfile.orientedY((x+.5)/w,(y+.5)/h,e)*oh-.5);check(output[y*w+x]==expected[oy*ow+ox],"canonical half-pixel clone tie EXIF"+e+" at"+x+","+y);}}}
    private static void cancellation()throws Exception{AtomicInteger accesses=new AtomicInteger();SpatialPreviewFilter.Pixels never=new SpatialPreviewFilter.Pixels(){public int width(){return 10;}public int height(){return 10;}public void read(int[] a,int y,int n){accesses.incrementAndGet();}public void write(int[] a,int y,int n){accesses.incrementAndGet();}};boolean interrupted=false;try{LocalEditsPreviewProfile.renderLocal(never,PhotoLocalEdits.NONE.add(PhotoLocalEdits.Mask.radial(.5,.5).parameters(10,0,0)),1,()->true,null);}catch(InterruptedIOException expected){interrupted=true;}check(interrupted&&accesses.get()==0,"cancel before IO");SpatialPreviewFilter.Pixels huge=new SpatialPreviewFilter.Pixels(){public int width(){return 65535;}public int height(){return 65535;}public void read(int[] a,int y,int n){throw new AssertionError("oversized patch read");}public void write(int[] a,int y,int n){throw new AssertionError("oversized patch write");}};boolean bounded=false;try{LocalEditsPreviewProfile.renderLocal(huge,PhotoLocalEdits.NONE.add(new PhotoLocalEdits.Clone(.4,.4,.5,.5,.25,.5,true)),1,()->false,null);}catch(IOException expected){bounded=expected.getMessage().contains("修复区域过大");}check(bounded,"oversized patch fails before allocation");}
    private static void streaming()throws Exception{final int w=6000,h=4000;AtomicInteger writes=new AtomicInteger();SpatialPreviewFilter.Pixels stream=new SpatialPreviewFilter.Pixels(){public int width(){return w;}public int height(){return h;}public void read(int[] row,int y,int n){check(n==1&&row.length>=w,"stream reads one row");for(int x=0;x<w;x++)row[x]=0xff000000|((x+y)&255)<<16|((y*3)&255)<<8|(x&255);}public void write(int[] row,int y,int n){check(n==1&&row.length>=w,"stream writes one row");writes.incrementAndGet();}};PhotoLocalEdits edit=PhotoLocalEdits.NONE.add(PhotoLocalEdits.Mask.radial(.5,.5).parameters(6,10,-10)).add(new PhotoLocalEdits.Clone(.25,.25,.7,.7,.05,.8,true));ArrayList<Double> progress=new ArrayList<>();LocalEditsPreviewProfile.renderLocal(stream,edit,1,()->false,progress::add);check(writes.get()>=h,"24MP streamed");check(progress.get(progress.size()-1)==1,"final progress");for(int i=1;i<progress.size();i++)check(progress.get(i)>=progress.get(i-1),"progress monotone");}
    private static int[] render(int[] input,int width,int height,PhotoLocalEdits edits,int exif)throws Exception{int[] output=input.clone();SpatialPreviewFilter.Pixels pixels=new SpatialPreviewFilter.Pixels(){public int width(){return width;}public int height(){return height;}public int exifOrientation(){return exif;}public void read(int[] row,int y,int count){System.arraycopy(output,y*width,row,0,width*count);}public void write(int[] row,int y,int count){System.arraycopy(row,0,output,y*width,width*count);}};LocalEditsPreviewProfile.of(ORIGINAL,edits).renderPixels(pixels,()->false,null);return output;}
}
